/// `":0"` and `":65535"`), while -1, -2, -100, `i32::MIN`, 65536, 70000 and
/// `i32::MAX` are all replaced by the "unset" sentinel -1. So the bound is
/// inclusive on both ends and 0 counts as valid.
pub fn is_port_valid(port: i32) -> bool {
    (0..=65535).contains(&port)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn scheme_rules() {
        assert!(is_scheme_valid("http"));
        assert!(is_scheme_valid("a1+-."));
        assert!(!is_scheme_valid(""));
        assert!(!is_scheme_valid("1http"));
        assert!(!is_scheme_valid("ht tp"));
        assert!(!is_scheme_valid("ht_tp"));
    }

    #[test]
    fn host_rules() {
        assert!(is_host_valid("example.com"));
        assert!(is_host_valid("localhost"));
        assert!(is_host_valid("1.2.3.4"));
        assert!(is_host_valid("un_der.com"));
        assert!(is_host_valid("[::1]"));
        assert!(!is_host_valid(""));
        assert!(!is_host_valid("a..b"));
        assert!(!is_host_valid("-bad.com"));
        assert!(!is_host_valid("bad-.com"));
        assert!(!is_host_valid("a b"));
        assert!(!is_host_valid("[::1"));
    }

    #[test]
    fn port_bounds_match_the_cxx_binary() {
        assert!(is_port_valid(0));
        assert!(is_port_valid(80));
        assert!(is_port_valid(65535));
        assert!(!is_port_valid(-1));
        assert!(!is_port_valid(-2));
        assert!(!is_port_valid(i32::MIN));
        assert!(!is_port_valid(65536));
        assert!(!is_port_valid(i32::MAX));
    }
}

